_sayableduration_plural_pl() {
    local n=$1
    if [ "${n}" -eq 1 ]; then echo "one"; return; fi
    local mod10=$(( n % 10 ))
    local mod100=$(( n % 100 ))
    if [ "${mod10}" -ge 2 ] && [ "${mod10}" -le 4 ] && { [ "${mod100}" -lt 12 ] || [ "${mod100}" -gt 14 ]; }; then echo "few"; return; fi
    echo "many"
}

